// -------- 029BN-T94-D2 Driver --------\nGxEPD2_BW<GxEPD2_290_T94_V2, GxEPD2_290_T94_V2::HEIGHT> display(\n  GxEPD2_290_T94_V2(EPD_CS, EPD_DC, EPD_RST, EPD_BUSY)\n);\n\nconst char* LINE1 = "Hello XIAO nRF54L15";\n\nvoid setup() {\n  Serial.begin(115200);\n  delay(2000);\n  Serial.println("=== EPaper Start ===");\n\n  // Close serial port to avoid TX(D1) interfering with CS(D1)\n  delay(100);\n  Serial.end();\n\n  // Directly specify using macros, fully consistent with pins_arduino.h\n  SPI.setPins(PIN_SPI_SCK, PIN_SPI_MISO, PIN_SPI_MOSI, -1);\n  SPI.begin();\n\n  // Pass 0 to disable GxEPD2 internal serial debug output\n  display.init(0);\n  display.setRotation(1);  // Landscape 296\xd7128\n  display.setTextColor(GxEPD_BLACK);\n  display.setFullWindow();\n\n  display.firstPage();\n  do {\n    display.fillScreen(GxEPD_WHITE);\n\n    // ---- LINE1: Large font, upper half ----\n    display.setFont(&FreeMonoBold12pt7b);\n    int16_t tbx, tby;\n    uint16_t tbw, tbh;\n    display.getTextBounds(LINE1, 0, 0, &tbx, &tby, &tbw, &tbh);\n    uint16_t x1 = (display.width()  - tbw) / 2 - tbx;\n    uint16_t y1 = display.height() / 2 - 4;\n    display.setCursor(x1, y1);\n    display.print(LINE1);\n\n  } while (display.nextPage());\n\n  display.hibernate();\n\n  // Reopen serial port for confirmation after screen refresh\n  Serial.begin(115200);\n  delay(100);\n  Serial.println("=== Done ===");\n}\n\nvoid loop() {\n  delay(1000000);\n}\n'})}),"\n",(0,r.jsx)(n.h3,{id:"resultado-4",children:"Resultado"}),"\n",(0,r.jsxs)(n.p,{children:["Despu\xe9s de cargar el programa, ",(0,r.jsx)(n.code,{children:"Hello XIAO nRF54L15"})," se mostrar\xe1 en la pantalla de papel electr\xf3nico."]}),"\n",(0,r.jsx)("div",{style:{textAlign:"center"},children:(0,r.jsx)("img",{src:"https://files.seeedstudio.com/wiki/XIAO_nRF54L15/Getting_Start/arduino/result_6.jpg",style:{width:800,height:"auto"}})}),"\n",(0,r.jsx)(n.h2,{id:"preguntas-frecuentes",children:"Preguntas frecuentes"}),"\n",(0,r.jsxs)(n.ul,{chi